{"name": "write_file", "arguments": {"file_path": "/path/to/project/app/reconcile.py", "content": "#!/usr/bin/env python3.12

import csv
from decimal import Decimal, getcontext
from datetime import datetime
from sys import argv, stderr

getcontext().prec = 2

def main(csv_file_path):
    transactions = {}
    try:
        with open(csv_file_path, newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                tx_id = row['tx_id']
                timestamp = row['timestamp'][:19]  # Remove timezone offset
                amount = row['amount']
                status = row['status']

                try:
                    amount = Decimal(amount)
                    timestamp = datetime.fromisoformat(timestamp)
                except (ValueError, TypeError):
                    continue

                if tx_id not in transactions or transactions[tx_id]['timestamp'] < timestamp:
                    transactions[tx_id] = {'timestamp': timestamp, 'amount': amount, 'status': status}

    except FileNotFoundError:
        print("Error: CSV file not found", file=stderr)
        exit(1)
    except PermissionError:
        print("Error: Permission denied", file=stderr)
        exit(1)
    except Exception as e:
        print(f"Error: {e}", file=stderr)
        exit(1)

    total_valid_amount = Decimal(0)
    valid_count = 0
    failed_count = 0

    for tx_id, tx_info in transactions.items():
        if tx_info['status'] == 'SUCCESS':
            total_valid_amount += tx_info['amount']
            valid_count += 1
        elif tx_info['status'] == 'FAILED':
            failed_count += 1

    result = {
        'total_valid_amount': float(total_valid_amount),
        'valid_count': valid_count,
        'failed_count': failed_count
    }

    print(result)

if __name__ == '__main__':
    if len(argv) != 2:
        print("Usage: python3.12 reconcile.py <csv_file_path>", file=stderr)
        exit(1)

    main(argv[1])", "record_as_artifact": true}}
